// Compile-Time Power Calculation
constexpr int power(int b, int e) {
    int res = 1;
    for (int i = 0; i < e; ++i) res *= b;
    return res;
}

// Result computed during compilation (100)
constexpr int R10 = power(10, 2);

// Context requiring a constant expression (array size)
int data[power(2, 4)]; // Array size is 16

// Context requiring a constant expression (case label)
void check(int x) {
    switch(x) {
        case power(3, 1): ; // Valid case label (3)
        default: ;
    }
}

// C++20 relaxation: Not evaluated at compile time if context permits
int runtime_val = power(5, 2); // May be runtime (optimization dependent)
// but guaranteed to be valid constexpr usage.
